def move_files_to_media(apps, schema_editor):
    Video = apps.get_model("studio", "Video")
    MediaFile = apps.get_model("studio", "MediaFile")
    for video in Video.objects.all().iterator():
        if not video.file and not video.drive_file_id:
            continue
        MediaFile.objects.create(
            content=video,
            kind="video",
            file=video.file.name if video.file else "",
            original_name=video.original_name,
            mime_type="video/mp4",
            size=video.size,
            drive_file_id=video.drive_file_id,
            status=video.file_status,
            error=video.file_error,
        )


